INSERT INTO repo_esd_objectives (esd_objective_id, domain, objective_no, text, status) VALUES ('ESD_SDG07_BEH_01', 'Behavioural', '1', 'The learner is able to apply and evaluate measures in order to increase energy efficiency and sufficiency in their personal sphere and to increase the share of renewable energy in their local energy mix.', 'Active'), ('ESD_SDG07_BEH_02', 'Behavioural', '2', 'The learner is able to apply basic principles to determine the most appropriate renewable energy strategy in a given situation.', 'Active'), ('ESD_SDG07_BEH_03', 'Behavioural', '3', 'The learner is able to analyse the impact and long-term effects of big energy projects (e.g. constructing an off-shore wind park) and energy related policies on different stakeholder groups (including nature).', 'Active'), ('ESD_SDG07_BEH_04', 'Behavioural', '4', 'The learner is able to influence public policies related to energy production, supply and usage.', 'Active'), ('ESD_SDG07_BEH_05', 'Behavioural', '5', 'The learner is able to compare and assess different business models and their suitability for different energy solutions and to influence energy suppliers to produce safe, reliable and sustainable energy.', 'Active'), ('ESD_SDG08_COG_01', 'Cognitive', '1', 'The learner understands the concepts of sustained, inclusive and sustainable economic growth, full and productive employment, and decent work, including the advancement of gender parity and equality, and knows about alternative economic models and indicators.', 'Active'), ('ESD_SDG08_COG_02', 'Cognitive', '2', 'The learner has knowledge about the distribution of formal employment rates per sector, informal employment, and unemployment in different world regions or nations, and which social groups are especially affected by unemployment.', 'Active'), ('ESD_SDG08_COG_03', 'Cognitive', '3', 'The learner understands the relation between employment and economic growth, and knows about other moderating factors like a growing labour force or new technologies that substitute jobs.', 'Active'), ('ESD_SDG08_COG_04', 'Cognitive', '4', 'The learner understands how low and decreasing wages for the labour force and very high wages and profits of managers and owners or shareholders are leading to inequalities, poverty, civil unrest, etc.', 'Active'), ('ESD_SDG08_COG_05', 'Cognitive', '5', 'The learner understands how innovation, entrepreneurship and new job creation can contribute to decent work and a sustainability-driven economy and to the decoupling of economic growth from the impacts of natural hazards and environmental degradation.', 'Active'), ('ESD_SDG08_SOC_01', 'Socio-emotional', '1', 'The learner is able to discuss economic models and future visions of economy and society critically and to communicate them in public spheres.', 'Active'), ('ESD_SDG08_SOC_02', 'Socio-emotional', '2', 'The learner is able to collaborate with others to demand fair wages, equal pay for equal work and labour rights from politicians and from their employer.', 'Active'), ('ESD_SDG08_SOC_03', 'Socio-emotional', '3', 'The learner is able to understand how one’s own consumption affects working conditions of others in the global economy.', 'Active'), ('ESD_SDG08_SOC_04', 'Socio-emotional', '4', 'The learner is able to identify their individual rights and clarify their needs and values related to work.', 'Active'), ('ESD_SDG08_SOC_05', 'Socio-emotional', '5', 'The learner is able to develop a vision and plans for their own economic life based on an analysis of their competencies and contexts.', 'Active'), ('ESD_SDG08_BEH_01', 'Behavioural', '1', 'The learner is able to engage with new visions and models of a sustainable, inclusive economy and decent work.', 'Active'), ('ESD_SDG08_BEH_02', 'Behavioural', '2', 'The learner is able to facilitate improvements related to unfair wages, unequal pay for equal work and bad working conditions.', 'Active'), ('ESD_SDG08_BEH_03', 'Behavioural', '3', 'The learner is able to develop and evaluate ideas for sustainability-driven innovation and entrepreneurship.', 'Active'), ('ESD_SDG08_BEH_04', 'Behavioural', '4', 'The learner is able to plan and implement entrepreneurial projects.', 'Active'), ('ESD_SDG08_BEH_05', 'Behavioural', '5', 'The learner is able to develop criteria and make responsible consumption choices as a means to support fair working conditions and efforts to decouple production from the impact of natural hazards and environmental degradation.', 'Active'), ('ESD_SDG09_COG_01', 'Cognitive', '1', 'The learner understands the concepts of sustainable infrastructure and industrialization and society’s needs for a systemic approach to their development.', 'Active'), ('ESD_SDG09_COG_02', 'Cognitive', '2', 'The learner understands the local, national and global challenges and conflicts in achieving sustainability in infrastructure and industrialization.', 'Active'), ('ESD_SDG09_COG_03', 'Cognitive', '3', 'The learner can define the term resilience in the context of infrastructure and spatial planning, understanding key concepts such as modularity and diversity, and apply it to their local community and nationwide.', 'Active'), ('ESD_SDG09_COG_04', 'Cognitive', '4', 'The learner knows the pitfalls of unsustainable industrialization and in contrast knows examples of resilient, inclusive, sustainable industrial development and the need for contingency planning.', 'Active'), ('ESD_SDG09_COG_05', 'Cognitive', '5', 'The learner is aware of new opportunities and markets for sustainability innovation, resilient infrastructure and industrial development.', 'Active'), ('ESD_SDG09_SOC_01', 'Socio-emotional', '1', 'The learner is able to argue for sustainable, resilient and inclusive infrastructure in their local area.', 'Active'), ('ESD_SDG09_SOC_02', 'Socio-emotional', '2', 'The learner is able to encourage their communities to shift their infrastructure and industrial development toward more resilient and sustainable forms.', 'Active'), ('ESD_SDG09_SOC_03', 'Socio-emotional', '3', 'The learner is able to find collaborators to develop sustainable and contextual industries that respond to our shifting challenges and also to reach new markets.', 'Active'), ('ESD_SDG09_SOC_04', 'Socio-emotional', '4', 'The learner is able to recognize and reflect on their own personal demands on the local infrastructure such as their carbon and water footprints and food miles.', 'Active'), ('ESD_SDG09_SOC_05', 'Socio-emotional', '5', 'The learner is able to understand that with changing resource availability (e. g. peak oil, peak everything) and other external shocks and stresses (e. g. natural hazards, conflicts) their own perspective and demands on infrastructure may need to shift radically regarding availability of renewable energy for ICT, transport options, sanitation options, etc.', 'Active'), ('ESD_SDG09_BEH_01', 'Behavioural', '1', 'The learner is able to identify opportunities in their own culture and nation for greener and more resilient approaches to infrastructure, understanding their overall benefits for societies, especially with regard to disaster risk reduction.', 'Active'), ('ESD_SDG09_BEH_02', 'Behavioural', '2', 'The learner is able to evaluate various forms of industrialization and compare their resilience.', 'Active'), ('ESD_SDG09_BEH_03', 'Behavioural', '3', 'The learner is able to innovate and develop sustainable enterprises to respond to their countries’ industrial needs.', 'Active'), ('ESD_SDG09_BEH_04', 'Behavioural', '4', 'The learner is able to access financial services such as loans or microfinance to support their own enterprises.', 'Active'), ('ESD_SDG09_BEH_05', 'Behavioural', '5', 'The learner is able to work with decision-makers to improve the uptake of sustainable infrastructure (including internet access).', 'Active'), ('ESD_SDG10_COG_01', 'Cognitive', '1', 'The learner knows different dimensions of inequality, their interrelations and applicable statistics.', 'Active'), ('ESD_SDG10_COG_02', 'Cognitive', '2', 'The learner knows indicators that measure and describe inequalities and understands their relevance for decision-making.', 'Active'), ('ESD_SDG10_COG_03', 'Cognitive', '3', 'The learner understands that inequality is a major driver for societal problems and individual dissatisfaction.', 'Active'), ('ESD_SDG10_COG_04', 'Cognitive', '4', 'The learner understands local, national and global processes that both promote and hinder equality (fiscal, wage, and social protection policies, corporate activities, etc. ).', 'Active'), ('ESD_SDG10_COG_05', 'Cognitive', '5', 'The learner understands ethical principles concerning equality and is aware of psychological processes that foster discriminative behaviour and decision making.', 'Active'), ('ESD_SDG10_SOC_01', 'Socio-emotional', '1', 'The learner is able to raise awareness about inequalities.', 'Active'), ('ESD_SDG10_SOC_02', 'Socio-emotional', '2', 'The learner is able to feel empathy for and to show solidarity with people who are discriminated against.', 'Active'), ('ESD_SDG10_SOC_03', 'Socio-emotional', '3', 'The learner is able to negotiate the rights of different groups based on shared values and ethical principles.', 'Active'), ('ESD_SDG10_SOC_04', 'Socio-emotional', '4', 'The learner becomes aware of inequalities in their surroundings as well as in the wider world and is able to recognize the problematic consequences.', 'Active'), ('ESD_SDG10_SOC_05', 'Socio-emotional', '5', 'The learner is able to maintain a vision of a just and equal world.', 'Active'), ('ESD_SDG10_BEH_01', 'Behavioural', '1', 'The learner is able to evaluate inequalities in their local environment in terms of quality (different dimensions, qualitative impact on individuals) and quantity (indicators, quantitative impact on individuals).', 'Active'), ('ESD_SDG10_BEH_02', 'Behavioural', '2', 'The learner is able to identify or develop an objective indicator to compare different groups, nations, etc. with respect to inequalities.', 'Active'), ('ESD_SDG10_BEH_03', 'Behavioural', '3', 'The learner is able to identify and analyse different types of causes and reasons for inequalities.', 'Active'), ('ESD_SDG10_BEH_04', 'Behavioural', '4', 'The learner is able to plan, implement and evaluate strategies to reduce inequalities.', 'Active'), ('ESD_SDG10_BEH_05', 'Behavioural', '5', 'The learner is able to engage in the development of public policies and corporate activities that reduce inequalities.', 'Active') ON CONFLICT DO NOTHING;